15|extension ZIPArchiveProvider {
16|    public func createWindowsZIP(at outputURL: URL, inputs: [URL]) throws {
17|        guard !FileManager.default.fileExists(atPath: outputURL.path) else {
18|            throw WindowsZIPProfileError.outputExists
19|        }
20|        let files = try WindowsZIPPreflight().collect(inputs: inputs)
21|        let stageURL = outputURL.deletingLastPathComponent().appending(
22|            path: "." + outputURL.lastPathComponent + ".staging-" + UUID().uuidString
23|        )
24|        var stageExists = false
25|        defer {
26|            if stageExists { try? FileManager.default.removeItem(at: stageURL) }
27|        }
28|
29|        let writer = try ZIPBridgeWriter(url: stageURL)
30|        stageExists = true
31|        for file in files {
32|            try writer.add(sourceURL: file.sourceURL, archivePath: file.archivePath)
33|            guard try file.fingerprint == SourceFingerprint(url: file.sourceURL) else {
34|                throw ArchiveError.sourceChanged
35|            }
36|        }
37|        try writer.finish()
38|        try syncFile(at: stageURL)
39|        try publishExclusively(stageURL: stageURL, outputURL: outputURL)
40|        stageExists = false
41|    }
42|
43|    private func syncFile(at url: URL) throws {
44|        let descriptor = url.withUnsafeFileSystemRepresentation { path -> Int32 in
45|            guard let path else { return -1 }
46|            return Darwin.open(path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW)
47|        }
48|        guard descriptor >= 0 else { throw WindowsZIPProfileError.io(errno) }
49|        defer { Darwin.close(descriptor) }
50|        guard fsync(descriptor) == 0 else { throw WindowsZIPProfileError.io(errno) }
51|    }
52|
53|    private func publishExclusively(stageURL: URL, outputURL: URL) throws {
54|        let linkResult = stageURL.withUnsafeFileSystemRepresentation { stagePath in
55|            outputURL.withUnsafeFileSystemRepresentation { outputPath in
56|                guard let stagePath, let outputPath else { return Int32(-1) }
57|                return Darwin.link(stagePath, outputPath)
58|            }
59|        }
60|        guard linkResult == 0 else {
61|            if errno == EEXIST { throw WindowsZIPProfileError.outputExists }
62|            throw WindowsZIPProfileError.io(errno)
63|        }
64|        do {
65|            try FileManager.default.removeItem(at: stageURL)
66|            try syncDirectory(at: outputURL.deletingLastPathComponent())
67|        } catch {
68|            try? FileManager.default.removeItem(at: outputURL)
69|            throw error
70|        }
71|    }
72|
73|    private func syncDirectory(at url: URL) throws {
74|        let descriptor = url.withUnsafeFileSystemRepresentation { path -> Int32 in
75|            guard let path else { return -1 }
76|            return Darwin.open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW)
77|        }
78|        guard descriptor >= 0 else { throw WindowsZIPProfileError.io(errno) }
79|        defer { Darwin.close(descriptor) }
80|        guard fsync(descriptor) == 0 else { throw WindowsZIPProfileError.io(errno) }
81|    }
