90|private struct SourceFingerprint: Equatable {
91|    let resourceIdentifier: String
92|    let fileSize: Int
93|    let modificationTime: TimeInterval
94|
95|    init(url: URL) throws {
96|        let values = try url.resourceValues(forKeys: [
97|            .fileResourceIdentifierKey,
98|            .fileSizeKey,
99|            .contentModificationDateKey,
100|            .isRegularFileKey,
101|            .isSymbolicLinkKey,
102|        ])
103|        guard values.isRegularFile == true, values.isSymbolicLink != true else {
104|            throw WindowsZIPProfileError.unsupportedItem(url.lastPathComponent)
105|        }
106|        resourceIdentifier = String(describing: values.fileResourceIdentifier)
107|        fileSize = values.fileSize ?? -1
108|        modificationTime = values.contentModificationDate?.timeIntervalSinceReferenceDate ?? -1
109|    }
