112|private struct WindowsZIPPreflight {
113|    private let resourceKeys: Set<URLResourceKey> = [
114|        .isRegularFileKey,
115|        .isDirectoryKey,
116|        .isSymbolicLinkKey,
117|        .fileResourceIdentifierKey,
118|        .fileSizeKey,
119|        .contentModificationDateKey,
120|    ]
121|
122|    func collect(inputs: [URL]) throws -> [WindowsZIPInputFile] {
123|        guard !inputs.isEmpty else { throw WindowsZIPProfileError.noInputs }
124|        var candidates: [(URL, String)] = []
125|        for input in inputs {
126|            let values = try input.resourceValues(forKeys: resourceKeys)
127|            if values.isSymbolicLink == true {
128|                throw WindowsZIPProfileError.unsupportedItem(input.lastPathComponent)
129|            }
130|            if values.isRegularFile == true {
131|                candidates.append((input, input.lastPathComponent))
132|            } else if values.isDirectory == true {
133|                candidates.append(contentsOf: try files(under: input))
134|            } else {
135|                throw WindowsZIPProfileError.unsupportedItem(input.lastPathComponent)
136|            }
137|        }
138|
139|        let normalized = try candidates.compactMap { sourceURL, relativePath -> WindowsZIPInputFile? in
140|            let components = relativePath.split(separator: "/").map(String.init)
141|            if shouldSuppress(components: components) { return nil }
142|            let archivePath = components
143|                .map { $0.precomposedStringWithCanonicalMapping }
144|                .joined(separator: "/")
145|            try validate(path: archivePath)
146|            return WindowsZIPInputFile(
147|                sourceURL: sourceURL,
148|                archivePath: archivePath,
149|                fingerprint: try SourceFingerprint(url: sourceURL)
150|            )
151|        }
152|        guard !normalized.isEmpty else { throw WindowsZIPProfileError.noInputs }
153|
154|        var seen: [String: String] = [:]
155|        for file in normalized {
156|            let key = file.archivePath.precomposedStringWithCanonicalMapping
157|                .lowercased(with: Locale(identifier: "en_US_POSIX"))
158|            if let existing = seen[key] {
159|                let ordered = [existing, file.archivePath].sorted(by: >)
160|                throw WindowsZIPProfileError.collision(ordered[0], ordered[1])
161|            }
162|            seen[key] = file.archivePath
163|        }
164|        return normalized.sorted {
165|            Array($0.archivePath.utf8).lexicographicallyPrecedes(Array($1.archivePath.utf8))
166|        }
167|    }
168|
169|    private func files(under root: URL) throws -> [(URL, String)] {
170|        var enumerationError: Error?
171|        guard let enumerator = FileManager.default.enumerator(
172|            at: root,
173|            includingPropertiesForKeys: Array(resourceKeys),
174|            options: [.skipsPackageDescendants],
175|            errorHandler: { _, error in
176|                enumerationError = error
177|                return false
178|            }
179|        ) else {
180|            throw WindowsZIPProfileError.unsupportedItem(root.lastPathComponent)
181|        }
182|        var result: [(URL, String)] = []
183|        let prefix = root.standardizedFileURL.path + "/"
184|        while let url = enumerator.nextObject() as? URL {
185|            let values = try url.resourceValues(forKeys: resourceKeys)
186|            guard url.standardizedFileURL.path.hasPrefix(prefix) else {
187|                throw WindowsZIPProfileError.unsupportedItem(url.lastPathComponent)
188|            }
189|            let relativePath = String(url.standardizedFileURL.path.dropFirst(prefix.count))
190|            if values.isSymbolicLink == true {
191|                throw WindowsZIPProfileError.unsupportedItem(relativePath)
192|            }
193|            if values.isRegularFile == true {
194|                result.append((url, relativePath))
195|            } else if values.isDirectory != true {
196|                throw WindowsZIPProfileError.unsupportedItem(relativePath)
197|            }
198|        }
199|        if let enumerationError { throw enumerationError }
200|        return result
201|    }
202|
203|    private func shouldSuppress(components: [String]) -> Bool {
204|        components.contains { component in
205|            component == ".DS_Store" || component == "__MACOSX" || component.hasPrefix("._")
206|        }
207|    }
208|
209|    private func validate(path: String) throws {
210|        let components = path.split(separator: "/", omittingEmptySubsequences: false).map(String.init)
211|        guard !components.isEmpty, path.utf16.count <= 180 else {
212|            throw WindowsZIPProfileError.invalidName(path)
213|        }
214|        let forbidden = CharacterSet(charactersIn: "<>:\"/\\|?*")
215|        let reserved = Set(["CON", "PRN", "AUX", "NUL"])
216|        for component in components {
217|            let upperStem = component.split(separator: ".", maxSplits: 1).first
218|                .map(String.init)?.uppercased() ?? ""
219|            let isNumberedDevice = (upperStem.hasPrefix("COM") || upperStem.hasPrefix("LPT"))
220|                && upperStem.count == 4
221|                && upperStem.last.map { ("1"..."9").contains(String($0)) } == true
222|            let invalid = component.isEmpty
223|                || component.utf16.count > 255
224|                || component.hasSuffix(".")
225|                || component.hasSuffix(" ")
226|                || component.unicodeScalars.contains { scalar in
227|                    scalar.value < 0x20 || forbidden.contains(scalar)
228|                }
229|                || reserved.contains(upperStem)
230|                || isNumberedDevice
231|            if invalid { throw WindowsZIPProfileError.invalidName(component) }
232|        }
233|    }
