260|                return awb_mz_writer_add_file(handle, sourcePath, archivePath)
261|            }
262|        }
263|        guard status == AWB_MZ_OK else {
264|            throw ZIPProviderErrorMapper.archiveError(for: status)
265|        }
266|    }
267|
268|    func finish() throws {
269|        guard handle != nil else { throw ArchiveError.helperFailed }
270|        let status = awb_mz_writer_close(&handle)
271|        guard status == AWB_MZ_OK else {
272|            throw ZIPProviderErrorMapper.archiveError(for: status)
