30|public actor ZIPArchiveProvider: ArchiveProvider {
31|    private let listingEntryLimit: Int
32|    private var reader: ZIPBridgeReader?
33|    private var entriesByID: [ArchiveEntryID: ArchiveEntrySnapshot] = [:]
34|    private var ordinalsByID: [ArchiveEntryID: UInt64] = [:]
35|
36|    public init() {
37|        listingEntryLimit = 1_000_000
38|    }
39|
40|    init(listingEntryLimit: Int) {
41|        self.listingEntryLimit = listingEntryLimit
42|    }
43|
44|    public func open(url: URL) throws -> ArchiveDocumentSnapshot {
45|        reader = nil
46|        entriesByID = [:]
47|        ordinalsByID = [:]
48|
49|        let openedReader = try ZIPBridgeReader(url: url)
50|        let bridgeEntries = try openedReader.allEntries(maximumCount: listingEntryLimit)
51|        var snapshots: [ArchiveEntrySnapshot] = []
52|        snapshots.reserveCapacity(bridgeEntries.count)
53|
54|        for bridgeEntry in bridgeEntries {
55|            guard let displayPath = String(bytes: bridgeEntry.nameBytes, encoding: .utf8) else {
56|                throw ArchiveError.unsupportedFormat
57|            }
58|            let validationPath = bridgeEntry.isDirectory && displayPath.hasSuffix("/")
59|                ? String(displayPath.dropLast())
60|                : displayPath
61|            do {
62|                try ArchivePathPolicy().validate(validationPath)
63|            } catch {
64|                throw ArchiveError.unsafePath
65|            }
66|
67|            let entry = ArchiveEntry(
68|                id: ArchiveEntryID(),
69|                rawPath: ArchivePathBytes(bridgeEntry.nameBytes),
70|                displayPath: displayPath
71|            )
72|            snapshots.append(ArchiveEntrySnapshot(
73|                entry: entry,
74|                compressedSize: bridgeEntry.compressedSize,
75|                uncompressedSize: bridgeEntry.uncompressedSize,
76|                modifiedAt: bridgeEntry.modifiedAt,
77|                isDirectory: bridgeEntry.isDirectory,
78|                isSymbolicLink: bridgeEntry.isSymbolicLink,
79|                isEncrypted: bridgeEntry.isEncrypted,
80|                usesUTF8FileName: bridgeEntry.usesUTF8FileName
81|            ))
82|        }
83|
84|        reader = openedReader
85|        entriesByID = Dictionary(uniqueKeysWithValues: snapshots.map { ($0.entry.id, $0) })
86|        ordinalsByID = Dictionary(uniqueKeysWithValues: snapshots.enumerated().map {
87|            ($0.element.entry.id, UInt64($0.offset))
88|        })
89|        return ArchiveDocumentSnapshot(sourceURL: url, format: .zip, entries: snapshots)
90|    }
91|
92|    public func readEntry(id: ArchiveEntryID, maximumBytes: UInt64) throws -> Data {
93|        guard
94|            let snapshot = entriesByID[id],
95|            let ordinal = ordinalsByID[id],
96|            let reader
97|        else {
98|            throw ArchiveError.helperFailed
99|        }
100|        guard !snapshot.isDirectory, !snapshot.isSymbolicLink else {
101|            throw ArchiveError.unsafePath
102|        }
103|        guard !snapshot.isEncrypted else {
104|            throw ArchiveError.passwordRequired
105|        }
106|        guard snapshot.uncompressedSize <= maximumBytes,
107|              snapshot.uncompressedSize <= UInt64(Int.max) else {
108|            throw ArchiveError.resourceLimit
109|        }
110|        return try reader.readEntry(
111|            ordinal: ordinal,
112|            expectedSize: snapshot.uncompressedSize,
113|            maximumBytes: maximumBytes
114|        )
115|    }
116|
117|    public func materializeEntry(
118|        id: ArchiveEntryID,
119|        under rootURL: URL,
120|        budget: ResourceBudget = .previewDefault
121|    ) throws -> URL {
122|        try Task.checkCancellation()
123|        guard let snapshot = entriesByID[id] else {
124|            throw ArchiveError.helperFailed
125|        }
126|        let decision = budget.evaluate(ResourceEstimate(
127|            compressedBytes: snapshot.compressedSize,
128|            expandedBytes: snapshot.uncompressedSize,
129|            entries: 1,
130|            depth: 1
131|        ))
132|        guard decision == .allow else { throw ArchiveError.resourceLimit }
133|        let data = try readEntry(id: id, maximumBytes: budget.maxExpandedBytes)
134|        try Task.checkCancellation()
135|        let output = try SecureFileMaterializer(rootURL: rootURL).write(
136|            data,
137|            relativePath: snapshot.entry.displayPath
138|        )
139|        try Task.checkCancellation()
140|        return output
141|    }
142|
143|    public func extractAll(
144|        under rootURL: URL,
145|        budget: ResourceBudget = .extractionDefault,
146|        progress: @Sendable (ZIPExtractionProgress) -> Void = { _ in }
147|    ) throws -> ZIPExtractionResult {
148|        try Task.checkCancellation()
149|        let snapshots = entriesByID.values.sorted {
150|            guard let left = ordinalsByID[$0.entry.id], let right = ordinalsByID[$1.entry.id] else {
151|                return $0.entry.displayPath < $1.entry.displayPath
152|            }
153|            return left < right
154|        }
155|        guard let reader else { throw ArchiveError.helperFailed }
156|        guard !snapshots.contains(where: { $0.isSymbolicLink }) else {
157|            throw ArchiveError.unsafePath
158|        }
159|        guard !snapshots.contains(where: { $0.isEncrypted }) else {
160|            throw ArchiveError.passwordRequired
161|        }
162|        try validateExtractionPaths(snapshots)
163|
164|        var compressedBytes: UInt64 = 0
165|        var expandedBytes: UInt64 = 0
166|        var maximumDepth: UInt64 = 0
167|        for snapshot in snapshots {
168|            let (nextCompressed, compressedOverflow) = compressedBytes.addingReportingOverflow(snapshot.compressedSize)
169|            let (nextExpanded, expandedOverflow) = expandedBytes.addingReportingOverflow(snapshot.uncompressedSize)
170|            guard !compressedOverflow, !expandedOverflow else { throw ArchiveError.resourceLimit }
171|            compressedBytes = nextCompressed
172|            expandedBytes = nextExpanded
173|            let path = snapshot.isDirectory && snapshot.entry.displayPath.hasSuffix("/")
174|                ? String(snapshot.entry.displayPath.dropLast())
175|                : snapshot.entry.displayPath
176|            maximumDepth = max(maximumDepth, UInt64(path.split(separator: "/").count))
177|        }
178|        guard budget.evaluate(ResourceEstimate(
179|            compressedBytes: compressedBytes,
180|            expandedBytes: expandedBytes,
181|            entries: UInt64(snapshots.count),
182|            depth: maximumDepth
183|        )) == .allow else {
184|            throw ArchiveError.resourceLimit
185|        }
186|
187|        let materializer = try SecureMaterializationSession(rootURL: rootURL)
188|        var completedEntries = 0
189|        var writtenBytes: UInt64 = 0
190|        progress(ZIPExtractionProgress(
191|            completedEntries: 0,
192|            totalEntries: snapshots.count,
193|            completedBytes: 0,
194|            totalBytes: expandedBytes
195|        ))
196|        for snapshot in snapshots {
197|            try Task.checkCancellation()
198|            let path = snapshot.isDirectory && snapshot.entry.displayPath.hasSuffix("/")
199|                ? String(snapshot.entry.displayPath.dropLast())
200|                : snapshot.entry.displayPath
201|            if snapshot.isDirectory {
202|                _ = try materializer.createDirectory(relativePath: path)
203|            } else {
204|                guard let ordinal = ordinalsByID[snapshot.entry.id] else {
205|                    throw ArchiveError.helperFailed
206|                }
207|                _ = try materializer.write(relativePath: path) { writer in
208|                    try reader.streamEntry(
209|                        ordinal: ordinal,
210|                        expectedSize: snapshot.uncompressedSize,
211|                        maximumBytes: snapshot.uncompressedSize,
212|                        writer: writer
213|                    ) { chunkBytes in
214|                        progress(ZIPExtractionProgress(
215|                            completedEntries: completedEntries,
216|                            totalEntries: snapshots.count,
217|                            completedBytes: writtenBytes + chunkBytes,
218|                            totalBytes: expandedBytes
219|                        ))
220|                    }
221|                }
222|                writtenBytes += snapshot.uncompressedSize
223|            }
224|            completedEntries += 1
225|            progress(ZIPExtractionProgress(
226|                completedEntries: completedEntries,
227|                totalEntries: snapshots.count,
228|                completedBytes: writtenBytes,
229|                totalBytes: expandedBytes
230|            ))
231|        }
232|        return ZIPExtractionResult(completedEntries: completedEntries, expandedBytes: writtenBytes)
233|    }
234|
235|    private func validateExtractionPaths(_ snapshots: [ArchiveEntrySnapshot]) throws {
236|        var canonicalPaths: Set<String> = []
237|        for snapshot in snapshots {
238|            let path = snapshot.isDirectory && snapshot.entry.displayPath.hasSuffix("/")
239|                ? String(snapshot.entry.displayPath.dropLast())
240|                : snapshot.entry.displayPath
241|            let canonical = path.decomposedStringWithCanonicalMapping.folding(
242|                options: [.caseInsensitive],
243|                locale: Locale(identifier: "en_US_POSIX")
244|            )
245|            guard canonicalPaths.insert(canonical).inserted else {
246|                throw ArchiveError.unsafePath
247|            }
248|        }
249|    }
