263|private final class ZIPBridgeReader {
264|    private var handle: OpaquePointer?
265|
266|    init(url: URL) throws {
267|        var opened: OpaquePointer?
268|        let status = url.withUnsafeFileSystemRepresentation { path in
269|            guard let path else { return Int32(AWB_MZ_INVALID_ARGUMENT) }
270|            return awb_mz_reader_open(path, &opened)
271|        }
272|        guard status == AWB_MZ_OK, let opened else {
273|            throw ZIPProviderErrorMapper.archiveError(for: status)
274|        }
275|        handle = opened
276|    }
277|
278|    deinit {
279|        awb_mz_reader_close(&handle)
280|    }
281|
282|    func allEntries(maximumCount: Int) throws -> [ZIPBridgeEntry] {
283|        guard let handle else { throw ArchiveError.helperFailed }
284|        guard maximumCount > 0 else { throw ArchiveError.resourceLimit }
285|        var result: [ZIPBridgeEntry] = []
286|        var info = awb_mz_entry_info()
287|        var status = awb_mz_reader_first(handle, &info)
288|        while status == AWB_MZ_OK {
289|            guard result.count < maximumCount else {
290|                throw ArchiveError.resourceLimit
291|            }
292|            result.append(try copy(info))
293|            status = awb_mz_reader_next(handle, &info)
294|        }
295|        guard status == AWB_MZ_END else {
296|            throw ZIPProviderErrorMapper.archiveError(for: status)
297|        }
298|        return result
299|    }
