301|    func readEntry(ordinal: UInt64, expectedSize: UInt64, maximumBytes: UInt64) throws -> Data {
302|        guard let handle else { throw ArchiveError.helperFailed }
303|        var info = awb_mz_entry_info()
304|        var status = awb_mz_reader_goto(handle, ordinal, &info)
305|        guard status == AWB_MZ_OK else {
306|            throw ZIPProviderErrorMapper.archiveError(for: status)
307|        }
308|        status = awb_mz_reader_open_current(handle)
309|        guard status == AWB_MZ_OK else {
310|            throw ZIPProviderErrorMapper.archiveError(for: status)
311|        }
312|
313|        var data = Data()
314|        data.reserveCapacity(Int(expectedSize))
315|        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
316|        var readError: Error?
317|        while true {
318|            do {
319|                try Task.checkCancellation()
320|            } catch {
321|                readError = CancellationError()
322|                break
323|            }
324|            let count = buffer.withUnsafeMutableBufferPointer { bytes in
325|                awb_mz_reader_read_current(handle, bytes.baseAddress, Int32(bytes.count))
326|            }
327|            if count == 0 { break }
328|            if count < 0 {
329|                readError = ZIPProviderErrorMapper.archiveError(for: count)
330|                break
331|            }
332|            let nextSize = UInt64(data.count) + UInt64(count)
333|            if nextSize > maximumBytes {
334|                readError = ArchiveError.resourceLimit
335|                break
336|            }
337|            data.append(buffer, count: Int(count))
338|        }
339|
340|        let closeStatus = awb_mz_reader_close_current(handle)
341|        if let readError { throw readError }
342|        guard closeStatus == AWB_MZ_OK else {
343|            throw ZIPProviderErrorMapper.archiveError(for: closeStatus)
344|        }
345|        guard UInt64(data.count) == expectedSize else {
346|            throw ArchiveError.corruptedArchive
347|        }
348|        return data
349|    }
350|
351|    func streamEntry(
